import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type VoiceNoteMessageProps = Record<string, any>;

// Static waveform pattern to represent audio peaks
const WAVE_PATTERN = [
  0.2, 0.3, 0.2, 0.4, 0.7, 0.9, 0.6, 0.4, 0.3, 0.2,
  0.4, 0.6, 0.4, 0.3, 0.2, 0.3, 0.5, 0.8, 1.0, 0.7,
  0.5, 0.3, 0.2, 0.4, 0.6, 0.8, 0.6, 0.4, 0.3, 0.2,
  0.2, 0.3, 0.5, 0.7, 0.6, 0.4, 0.2, 0.3, 0.5, 0.8,
  0.9, 0.7, 0.5, 0.3, 0.2, 0.4, 0.6, 0.5, 0.3, 0.2,
  0.4, 0.7, 0.9, 0.6, 0.4, 0.2, 0.3, 0.5, 0.4, 0.2
];

const VoiceNoteMessage: React.FC<VoiceNoteMessageProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 10,
  avatarUrl = "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?q=80&w=200&auto=format&fit=crop",
  senderName = "Noel Mack",
  senderRole = "Studio Chief Branding Officer",
  messageText = "Sending over my thoughts...",
  messageTime = "8:00 PM",
  voiceNoteDuration = "00:05",
  accentColor = "#7be15e",
  glassOpacity = 0.15,
  blurAmount = 24,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background handling
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // A subtle gradient behind everything to make the glassmorphism pop
  const bgGradient = transparentBackground 
    ? "none" 
    : `radial-gradient(circle at 30% 50%, #2a1a1a 0%, ${backgroundColor} 100%)`;

  // Entrance Animations
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 },
  });

  const message1TranslateY = interpolate(entranceSpring, [0, 1], [50, 0]);
  const message1Opacity = interpolate(entranceSpring, [0, 1], [0, 1]);

  const message2Spring = spring({
    frame: frame - 15, // Staggered start
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 },
  });

  const message2TranslateY = interpolate(message2Spring, [0, 1], [50, 0]);
  const message2Opacity = interpolate(message2Spring, [0, 1], [0, 1]);

  const avatarSpring = spring({
    frame: frame - 5,
    fps,
    config: { damping: 12, stiffness: 150 },
  });
  const avatarScale = interpolate(avatarSpring, [0, 1], [0.5, 1]);

  // Voice Note Animation Logic
  // Progress sweeps from 0 to 1 over 80% of the video duration
  const playbackDurationFrames = fps * durationInSeconds * 0.8;
  const rawProgress = Math.max(0, (frame - 30) / playbackDurationFrames); // Start playing after 1 second
  const playProgress = Math.min(1, rawProgress);
  
  // Format current playback time
  const currentPlaySeconds = Math.floor(playProgress * 5); // Assuming 5 seconds total as per text
  const currentPlayTimeStr = `00:0${currentPlaySeconds}`;

  // Shared Glass Style
  const glassStyle: React.CSSProperties = {
    background: `linear-gradient(135deg, rgba(255,255,255,${glassOpacity + 0.05}) 0%, rgba(255,255,255,${glassOpacity - 0.05}) 100%)`,
    backdropFilter: `blur(${blurAmount}px)`,
    WebkitBackdropFilter: `blur(${blurAmount}px)`,
    border: "1px solid rgba(255,255,255,0.15)",
    boxShadow: "0 24px 48px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.2)",
    borderRadius: "28px",
    padding: "32px 40px",
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    width: "100%",
    position: "relative",
    overflow: "hidden",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: bgGradient,
        fontFamily: "'Inter', sans-serif",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: width * 0.6,
          maxWidth: "1150px",
          display: "flex",
          flexDirection: "column",
          gap: "24px",
          position: "relative",
        }}
      >
        {/* Message 1 Container */}
        <div
          style={{
            position: "relative",
            width: "100%",
            transform: `translateY(${message1TranslateY}px)`,
            opacity: message1Opacity,
            transition: "none",
          }}
        >
          {/* Avatar (Positioned outside the bubble to the left) */}
          <div
            style={{
              position: "absolute",
              left: "-110px",
              top: "50%",
              transform: `translateY(-50%) scale(${avatarScale})`,
              width: "80px",
              height: "80px",
              borderRadius: "50%",
              backgroundImage: `url(${avatarUrl})`,
              backgroundSize: "cover",
              backgroundPosition: "center",
              boxShadow: "0 8px 16px rgba(0,0,0,0.3)",
              border: "2px solid rgba(255,255,255,0.1)",
              transition: "none",
            }}
          />

          {/* First Glass Bubble */}
          <div style={glassStyle}>
            <div style={{ display: "flex", flexDirection: "row", alignItems: "baseline" }}>
              <span
                style={{
                  color: accentColor,
                  fontSize: "32px",
                  fontWeight: 600,
                  letterSpacing: "-0.5px",
                  textShadow: "0 2px 4px rgba(0,0,0,0.2)",
                }}
              >
                {senderName}
              </span>
              <span
                style={{
                  color: accentColor,
                  fontSize: "32px",
                  fontWeight: 500,
                  opacity: 0.9,
                  marginLeft: "8px",
                }}
              >
                - {senderRole}
              </span>
            </div>

            <div
              style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "space-between",
                alignItems: "flex-end",
              }}
            >
              <span
                style={{
                  color: "white",
                  fontSize: "52px",
                  fontWeight: 400,
                  letterSpacing: "-1px",
                  textShadow: "0 2px 8px rgba(0,0,0,0.3)",
                }}
              >
                {messageText}
              </span>
              <span
                style={{
                  color: "rgba(255,255,255,0.5)",
                  fontSize: "24px",
                  fontWeight: 400,
                  marginBottom: "8px",
                }}
              >
                {messageTime}
              </span>
            </div>
          </div>
        </div>

        {/* Message 2 Container (Voice Note) */}
        <div
          style={{
            width: "100%",
            transform: `translateY(${message2TranslateY}px)`,
            opacity: message2Opacity,
            transition: "none",
          }}
        >
          <div style={{ ...glassStyle, padding: "32px 40px 24px 40px" }}>
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                gap: "24px",
              }}
            >
              {/* Play/Pause Button */}
              <div
                style={{
                  width: "32px",
                  height: "40px",
                  display: "flex",
                  flexDirection: "row",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div style={{ width: "10px", height: "100%", backgroundColor: "white", borderRadius: "4px" }} />
                <div style={{ width: "10px", height: "100%", backgroundColor: "white", borderRadius: "4px" }} />
              </div>

              {/* Waveform */}
              <div
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  height: "60px",
                  gap: "6px",
                  paddingRight: "10px",
                }}
              >
                {WAVE_PATTERN.map((baseAmplitude, index) => {
                  const normalizedIndex = index / WAVE_PATTERN.length;
                  const isPlayed = normalizedIndex <= playProgress;
                  
                  // Continuous animation logic to make the voice note feel alive
                  // Bars bounce slightly based on time and their position
                  const timePhase = frame * 0.15;
                  const posPhase = index * 0.3;
                  // Use sine wave to create a pulsing multiplier between 0.6 and 1.2
                  const bouncePulse = Math.sin(timePhase - posPhase);
                  const multiplier = interpolate(bouncePulse, [-1, 1], [0.5, 1.2], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp"
                  });
                  
                  // If the bar is near the playhead, it bounces higher
                  const distanceToPlayhead = Math.abs(normalizedIndex - playProgress);
                  const isActiveZone = distanceToPlayhead < 0.1 && playProgress > 0 && playProgress < 1;
                  const activeBoost = isActiveZone ? 1.5 : 1.0;

                  const finalHeight = baseAmplitude * 100 * multiplier * activeBoost;
                  
                  // Color transitions from white (played) to gray (unplayed)
                  const barColor = isPlayed ? "rgba(255,255,255,1)" : "rgba(255,255,255,0.4)";

                  return (
                    <div
                      key={index}
                      style={{
                        width: "6px",
                        height: `${Math.max(4, Math.min(finalHeight, 100))}%`, // Clamp between 4% and 100%
                        backgroundColor: barColor,
                        borderRadius: "3px",
                        transition: "none",
                        boxShadow: isPlayed ? "0 0 8px rgba(255,255,255,0.3)" : "none",
                      }}
                    />
                  );
                })}
              </div>
            </div>

            {/* Timers Row */}
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "space-between",
                paddingLeft: "56px", // Align with waveform start (32px button + 24px gap)
                marginTop: "16px",
              }}
            >
              <span
                style={{
                  color: "white",
                  fontSize: "24px",
                  fontWeight: 500,
                  letterSpacing: "0.5px",
                }}
              >
                {playProgress < 1 ? currentPlayTimeStr : voiceNoteDuration}
              </span>
              <span
                style={{
                  color: "rgba(255,255,255,0.5)",
                  fontSize: "24px",
                  fontWeight: 400,
                }}
              >
                {messageTime}
              </span>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default VoiceNoteMessage;